@prefix : <http://www.semanticweb.org/matej/ontologies/2026/2/untitled-ontology-45/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

:Court a owl:Class ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:onClass :Location ;
  owl:onProperty :takesPlaceIn ;
  owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ],
  [ a owl:Restriction ;
  owl:maxQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
  owl:onClass :Verdict ;
  owl:onProperty :issuesVerdict ],
  :Organisation .

:issuesVerdict a owl:FunctionalProperty,
  owl:ObjectProperty ;
  rdfs:comment "The property issuesVerdict is functional because a court should issue only one verdict." ;
  rdfs:domain :Judge ;
  rdfs:range :Verdict ;
  rdfs:subPropertyOf owl:topObjectProperty .

:Verdict a owl:Class .

@prefix : <http://www.semanticweb.org/matej/ontologies/2026/2/untitled-ontology-45/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

:LawFirm a owl:Class ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ;
  owl:onClass :Client ;
  owl:onProperty :represents ],
  :Organisation .

:Client a owl:Class ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:onProperty :represents ;
  owl:someValuesFrom :Case ],
  :Person .

:represents a owl:ObjectProperty ;
  rdfs:domain :Lawyer ;
  rdfs:range :Client ;
  rdfs:subPropertyOf owl:topObjectProperty .

@prefix : <http://www.semanticweb.org/hossnahosseini/ontologies/2026/2/RealEstateOntology/> .
