@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

:Apartment a owl:Class ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:allValuesFrom :Amenities ;
  owl:onProperty :has ],
  [ a owl:Restriction ;
  owl:maxQualifiedCardinality "10"^^xsd:nonNegativeInteger ;
  owl:onClass :Amenities ;
  owl:onProperty :has ],
  :Properties .

:Amenities a owl:Class ;
  rdfs:comment "an amenitiy is omething extra included" ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:onProperty :locatedIn ;
  owl:someValuesFrom :Properties ] .

:has a owl:ObjectProperty,
  owl:SymmetricProperty ;
  rdfs:comment "A Person has the legal status a mortgage. A person can only have the legal status mortgage" ;
  rdfs:domain :Person .

@prefix : <http://www.semanticweb.org/maxif/ontologies/2026/2/untitled-ontology-7/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

:Exercise a owl:Class ;
  rdfs:comment "Each exercise trains at least one muscle group" ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:onProperty :achievesGoals ;
  owl:someValuesFrom :TrainingGoal ],
  [ a owl:Restriction ;
  owl:onProperty :causesInjury ;
  owl:someValuesFrom :MuscleGroup ],
  [ a owl:Restriction ;
  owl:allValuesFrom :MuscleGroup ;
  owl:onProperty :trainsMuscle ] .

:achievesGoals a owl:ObjectProperty ;
  rdfs:domain :NutritionPlans ;
  rdfs:range :TrainingGoal .

:TrainingGoal a owl:Class ;
  rdfs:comment "Trainer leads to at least one training goal and is not allowed to lead to other types of entities." ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:allValuesFrom :TrainingGoal ;
  owl:onProperty :leadsTo ] .

@prefix : <http://www.semanticweb.org/timhubmann/ontologies/2026/2/Aufgabe-Tim/> .
