@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

:Camera a owl:Class ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:allValuesFrom :Camera_details ;
  owl:onProperty :consistOf ],
  [ a owl:Restriction ;
  owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
  owl:onClass :Lens ;
  owl:onProperty :hasLens ],
  [ a owl:Restriction ;
  owl:onClass :camera_brand ;
  owl:onProperty :manufacturedBy ;
  owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ],
  :Equipment .

:Camera_details a owl:Class ;
  rdfs:subClassOf :Equipment .

:consistOf a owl:AsymmetricProperty,
  owl:ObjectProperty ;
  rdfs:comment "Team consists of min 1 Photographer, but Photographer doesn't consist of Team" ;
  rdfs:domain :Team ;
  rdfs:range :Photographer .

@prefix : <http://www.semanticweb.org/user/ontologies/2026/2/Fashion_4Lecture/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

:Jeans a owl:Class ;
  rdfs:comment """Jeans are only made out of cotton. Jeans must be made out of material to exist.
Jeans are sold by at least one brand.""" ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:onProperty :isSoldBy ;
  owl:someValuesFrom :Brand ],
  [ a owl:Restriction ;
  owl:allValuesFrom :Cotton ;
  owl:onProperty :isMadeOf ],
  :Bottom .

:Cotton a owl:Class ;
  rdfs:comment "Cotton is suitable for at least one kind of weather condition." ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:onProperty :isSuitableFor ;
  owl:someValuesFrom :Weather ],
  :Material .

:isMadeOf a owl:ObjectProperty ;
  rdfs:comment """A ClothingItem is made of a material.
Inverse: A material is used for a ClothingItem.""" ;
  rdfs:domain :ClothingItem ;
  rdfs:range :Material .

@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

:Venues a owl:Class ;
  rdfs:subClassOf [ a owl:Restriction ;
  owl:allValuesFrom :Location ;
  owl:onProperty :locatedIn ] .

:Location a owl:Class .

:locatedIn a owl:AsymmetricProperty, owl:ObjectProperty, owl:TransitiveProperty ;
  rdfs:comment "A Venue can only be locatedIn a Location. A EventTypes can only be locatedIn Venues. If a EventTypes is locatedIn a Venue, the Venue is locatedIn a Location."  .

