  owl:allValuesFrom :TrainingGoal ;
  owl:onProperty :leadsTo ] .

:Recipe rdf:type owl:Class .

:hasCategory rdf:type owl:ObjectProperty ;
             rdfs:domain :Recipe ;
             rdfs:range :RecipeCategory ,
                        [ rdf:type owl:Restriction ;
                          owl:onProperty :hasCategory ;
                          owl:maxQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
                          owl:onClass :RecipeCategory
                        ] .

:RecipeCategory rdf:type owl:Class .

:Recipe rdf:type owl:Class .

:hasIngredient rdf:type owl:ObjectProperty ;
               rdfs:domain :Recipe ,
                           [ rdf:type owl:Restriction ;
                             owl:onProperty :hasIngredient ;
                             owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
                             owl:onClass :Ingredient
                           ] ;
               rdfs:range :Ingredient .

:Ingredient rdf:type owl:Class .

:Caregiver rdf:type owl:Class ;
           rdfs:subClassOf :Person ,
                           [ rdf:type owl:Restriction ;
                             owl:onProperty :isEmployed ;
                             owl:allValuesFrom :GroomingSalon
                           ] .

:isEmployed rdf:type owl:ObjectProperty .

:GroomingSalon rdf:type owl:Class ;
               rdfs:subClassOf :PetCareLocation .

:Recipe rdf:type owl:Class .

:hasNutritionalInformation rdf:type owl:ObjectProperty ;
                           rdfs:domain :Recipe ;
                           rdfs:range :NutritionalInformation ,
                                      [ rdf:type owl:Restriction ;
                                        owl:onProperty :hasNutritionalInformation ;
                                        owl:maxQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
                                        owl:onClass :NutritionalInformation
                                      ] .

:NutritionalInformation rdf:type owl:Class .

